import { readFileSync, writeFileSync } from 'node:fs';

const handler = readFileSync('supabase/functions/fastener-weight/handler.ts', 'utf8');
const entry = readFileSync('supabase/functions/fastener-weight/index.ts', 'utf8')
  .replace("import { handleFastenerWeight } from './handler.ts';", '');
writeFileSync('deployment/fastener-weights/fastener-weight.ts',
  '// Generated by scripts/prepare-fastener-weight-function.mjs. Paste into Dashboard index.ts.\n' + handler + entry);
console.log('Prepared standalone fastener-weight Edge Function.');
